1	export type Item = {
2	  type: string;
3	  material?: string;
4	  cursed?: boolean;
5	  enchantment?: number;
6	};
7	
8	export type QuoteStep = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: string;
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioOutcome = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	
57	// The MHPCO price list. The spec states an insurance value and a base premium
58	// per item as a PAIR, so they live in one row rather than two parallel tables:
59	// a new item type cannot be added to one column and forgotten in the other.
60	//
61	// The two columns happen to sit at a 10:1 ratio for every current item, but the
62	// spec never states that as a rule — it lists both numbers for each item. So
63	// the premium is not derived from the insurance value; a future item priced off
64	// that ratio has somewhere to go.
65	const PRICE_LIST = {
66	  sword: { insuranceValue: 1000, basePremium: 100 },
67	  amulet: { insuranceValue: 600, basePremium: 60 },
68	  staff: { insuranceValue: 800, basePremium: 80 },
69	  potion: { insuranceValue: 400, basePremium: 40 },
70	  rune: { insuranceValue: 250, basePremium: 25 },
71	  moonstone: { insuranceValue: 250, basePremium: 25 },
72	} satisfies Record<string, { insuranceValue: number; basePremium: number }>;
73	
74	type InsurableType = keyof typeof PRICE_LIST;
75	
76	const isInsurableType = (type: string): type is InsurableType =>
77	  type in PRICE_LIST;
78	
79	const FIRST_INSURANCE_PERCENT = 10;
80	
81	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
82	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
83	// intermediates to stay exact, so every percentage goes through here.
84	const PERCENT_WHOLE = 100;
85	
86	const percentOf = (amount: number, percent: number): number =>
87	  (amount * percent) / PERCENT_WHOLE;
88	
89	// Rounding always favours MHPCO: premiums round up, payouts round down.
90	const roundPremium = (amount: number): number => Math.ceil(amount);
91	
92	const basePremiumOfType = (type: string): number =>
93	  PRICE_LIST[type as InsurableType].basePremium;
94	
95	const BLOCK_SIZE = 3;
96	const BLOCK_BASE_PREMIUM = 60;
97	
98	// Counts repeats among plain type names. Callers project whatever they hold
99	// (insured items, damage entries) down to the type strings they want counted,
100	// so nothing has to be dressed up as an Item just to be tallied.
101	const countOccurrences = (values: string[]): Map<string, number> => {
102	  const counts = new Map<string, number>();
103	  for (const value of values) {
104	    counts.set(value, (counts.get(value) ?? 0) + 1);
105	  }
106	  return counts;
107	};
108	
109	const typesOf = (items: Item[]): string[] => items.map((item) => item.type);
110	
111	// The counterpart of typesOf for the other side of a claim. Both feed
112	// countOccurrences, which compares insured types against damaged ones.
113	const damagedTypesOf = (damages: Damage[]): string[] =>
114	  damages.map((damage) => damage.itemType);
115	
116	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
117	
118	// A building block is exactly 3 alike components. Blocks are only offered on
119	// components, never on main items, and only at exactly 3 — 4 runes are priced
120	// per item, not as a block plus one.
121	const formsBuildingBlock = (type: string, count: number): boolean =>
122	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
123	
124	// A group of alike items is priced as a building block if it forms one, and
125	// per item otherwise.
126	const groupBasePremiumOf = (type: string, count: number): number =>
127	  formsBuildingBlock(type, count)
128	    ? BLOCK_BASE_PREMIUM
129	    : count * basePremiumOfType(type);
130	
131	// The policy base premium is the sum of the base premiums of each group of
132	// alike items.
133	const policyBasePremiumOf = (items: Item[]): number =>
134	  [...countOccurrences(typesOf(items))].reduce(
135	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
136	    0,
137	  );
138	
139	// Item-specific surcharges are additive percentages of the affected item's OWN
140	// base premium — they never compound with each other, and never apply to the
141	// policy total.
142	const CURSE_PERCENT = 50;
143	const HIGH_ENCHANTMENT_PERCENT = 30;
144	const HIGH_ENCHANTMENT_THRESHOLD = 5;
145	
146	const isCursed = (item: Item): boolean => item.cursed === true;
147	
148	const isHighlyEnchanted = (item: Item): boolean =>
149	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
150	
151	const surchargePercentOf = (item: Item): number =>
152	  (isCursed(item) ? CURSE_PERCENT : 0) +
153	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0);
154	
155	const itemSurchargesOf = (items: Item[]): number =>
156	  items.reduce(
157	    (total, item) =>
158	      total + percentOf(basePremiumOfType(item.type), surchargePercentOf(item)),
159	    0,
160	  );
161	
162	const LOYALTY_PERCENT = 20;
163	const LOYALTY_THRESHOLD_YEARS = 2;
164	const FOLLOW_UP_CONTRACT_PERCENT = 15;
165	
166	const isLongStanding = (customer: Customer): boolean =>
167	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
168	
169	// Policy-wide modifiers are additive percentages of the policy base premium:
170	// they never compound with each other. A discount is simply a negative
171	// percentage, so surcharges and discounts sum in a single list.
172	const policyModifierPercentOf = (
173	  customer: Customer,
174	  isFollowUpContract: boolean,
175	): number =>
176	  FIRST_INSURANCE_PERCENT +
177	  (isLongStanding(customer) ? -LOYALTY_PERCENT : 0) +
178	  (isFollowUpContract ? -FOLLOW_UP_CONTRACT_PERCENT : 0);
179	
180	// Only items on the MHPCO price list can be insured. This runs before any
181	// pricing, so every later PRICE_LIST lookup is guaranteed to hit a row.
182	const rejectIfUnknownItemType = (items: Item[]): void => {
183	  for (const item of items) {
184	    if (!isInsurableType(item.type)) {
185	      throw new Error(`unknown item type ${item.type}`);
186	    }
187	  }
188	};
189	
190	const processQuote = (
191	  step: QuoteStep,
192	  customer: Customer,
193	  isFollowUpContract: boolean,
194	): QuoteResult => {
195	  rejectIfUnknownItemType(step.items);
196	
197	  const basePremium = policyBasePremiumOf(step.items);
198	  const policyModifiers = percentOf(
199	    basePremium,
200	    policyModifierPercentOf(customer, isFollowUpContract),
201	  );
202	
203	  return {
204	    premium: roundPremium(
205	      basePremium +
206	        itemSurchargesOf(step.items) +
207	        policyModifiers +
208	        PROCESSING_FEE,
209	    ),
210	  };
211	};
212	
213	const insuranceValueOfType = (type: string): number =>
214	  PRICE_LIST[type as InsurableType].insuranceValue;
215	
216	const DEDUCTIBLE = 100;
217	const CAP_MULTIPLIER = 2;
218	
219	// Rounding always favours MHPCO: payouts round down.
220	const roundPayout = (amount: number): number => Math.floor(amount);
221	
222	const insuranceSumOf = (items: Item[]): number =>
223	  items.reduce((sum, item) => sum + insuranceValueOfType(item.type), 0);
224	
225	// A policy is created by a quote step and accumulates claims against its cap.
226	type Policy = {
227	  items: Item[];
228	  remainingCap: number;
229	};
230	
231	// The cap is twice the insurance sum of the covered items. It is derived from
232	// the UNMODIFIED insurance values: neither premium surcharges nor the building
233	// block discount move it, so it is computed from the items alone.
234	const openPolicyFor = (items: Item[]): Policy => ({
235	  items,
236	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(items),
237	});
238	
239	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
240	
241	// Distinct from HIGH_ENCHANTMENT_THRESHOLD (5) above, which bands an item as
242	// risky enough to carry a premium SURCHARGE. This higher bar marks an item as
243	// volatile: MHPCO caps its exposure by reimbursing only half the damage. Two
244	// unrelated rules that happen to both read the enchantment level — they are
245	// free to move independently, so they get independent names and constants.
246	const VOLATILE_ENCHANTMENT_THRESHOLD = 8;
247	const VOLATILE_REIMBURSEMENT_PERCENT = 50;
248	
249	const isVolatilelyEnchanted = (item: Item): boolean =>
250	  (item.enchantment ?? 0) >= VOLATILE_ENCHANTMENT_THRESHOLD;
251	
252	const DRAGON_MATERIAL = "dragon";
253	const FULL_REIMBURSEMENT_PERCENT = 100;
254	
255	const isDragonMaterial = (item: Item): boolean =>
256	  item.material === DRAGON_MATERIAL;
257	
258	// Special clauses in precedence order. Dragon material is fully reimbursed, but
259	// where an item is also volatilely enchanted the 50 % rule wins.
260	//
261	// NOTE: the dragon branch is currently indistinguishable from the default —
262	// full reimbursement is what an ordinary item gets anyway, and every spec
263	// example pairing dragon material with enchantment >= 8 is decided by the
264	// volatile rule above it. No test constrains this branch. It is written out
265	// because the spec states it as a rule, so that it is represented rather than
266	// accidental if the default ever stops being full reimbursement.
267	const reimbursementPercentFor = (item: Item): number => {
268	  if (isVolatilelyEnchanted(item)) return VOLATILE_REIMBURSEMENT_PERCENT;
269	  if (isDragonMaterial(item)) return FULL_REIMBURSEMENT_PERCENT;
270	  return FULL_REIMBURSEMENT_PERCENT;
271	};
272	
273	// The deductible is withheld once per damaged item, so it is subtracted per
274	// damage entry rather than once from the incident total. Special clauses reduce
275	// the reimbursement first; the deductible always comes last.
276	const netPayableFor = (damage: Damage, item: Item): number =>
277	  percentOf(damage.amount, reimbursementPercentFor(item)) - DEDUCTIBLE;
278	
279	// The insured item a damage entry refers to. The cast is safe by construction:
280	// rejectIfOverclaimed runs before any payout is computed and throws for any
281	// damage type whose damaged count exceeds its insured count. An uninsured type
282	// has an insured count of 0, so a single damage entry naming it is already
283	// overclaimed and never reaches here — every type that does reach here has at
284	// least one matching item in the policy.
285	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
286	  policy.items.find((item) => item.type === damage.itemType) as Item;
287	
288	// Named for what it sums: each entry has already had its deductible withheld
289	// by netPayableFor, so this is the payable total, not the reimbursement total.
290	const totalPayableFor = (incident: Incident, policy: Policy): number =>
291	  incident.damages.reduce(
292	    (total, damage) =>
293	      total + netPayableFor(damage, insuredItemFor(damage, policy)),
294	    0,
295	  );
296	
297	// A policy covers a fixed set of items, so a claim cannot report more damaged
298	// items of a type than the policy actually covers.
299	const rejectIfOverclaimed = (incident: Incident, policy: Policy): void => {
300	  const insured = countOccurrences(typesOf(policy.items));
301	  const damaged = countOccurrences(damagedTypesOf(incident.damages));
302	
303	  for (const [type, damagedCount] of damaged) {
304	    const insuredCount = insured.get(type) ?? 0;
305	    if (damagedCount > insuredCount) {
306	      throw new Error(
307	        `claim reports ${damagedCount} damaged ${type}(s) but the policy covers ${insuredCount}`,
308	      );
309	    }
310	  }
311	};
312	
313	const rejectIfNegativeDamage = (incident: Incident): void => {
314	  for (const damage of incident.damages) {
315	    if (damage.amount < 0) {
316	      throw new Error(
317	        `damage to ${damage.itemType} has a negative amount ${damage.amount}`,
318	      );
319	    }
320	  }
321	};
322	
323	// Pure: reports what the claim pays and what the cap would be left at. The
324	// caller owns writing the depleted cap back to the policy.
325	const processClaim = (step: ClaimStep, policy: Policy): ClaimResult => {
326	  rejectIfNegativeDamage(step.incident);
327	  rejectIfOverclaimed(step.incident, policy);
328	
329	  const uncappedPayout = roundPayout(totalPayableFor(step.incident, policy));
330	  // The total payout per policy is capped; a claim gets whatever cap is left.
331	  const payout = Math.min(uncappedPayout, policy.remainingCap);
332	
333	  return { payout, remainingCap: policy.remainingCap - payout };
334	};
335	
336	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
337	  const policies = new Map<number, Policy>();
338	  let quotesSoFar = 0;
339	
340	  const results = scenario.steps.map((step, index): StepResult => {
341	    if (isClaimStep(step)) {
342	      const policy = policies.get(step.policy) as Policy;
343	      const result = processClaim(step, policy);
344	      // Claims deplete the cap for every later claim against this policy.
345	      policy.remainingCap = result.remainingCap;
346	      return result;
347	    }
348	
349	    const result = processQuote(step, scenario.customer, quotesSoFar > 0);
350	    quotesSoFar += 1;
351	    policies.set(index, openPolicyFor(step.items));
352	    return result;
353	  });
354	
355	  return { results };
356	};
