3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) {
6	    chunks.push(chunk as Buffer);
7	  }
8	  return Buffer.concat(chunks).toString("utf8");
9	};
10	
11	// A rejected scenario reports the reason on stderr and writes nothing to
12	// stdout: a partial or absent result must never look like a valid answer.
13	try {
14	  const scenario = JSON.parse(await readStdin()) as Scenario;
15	
16	  process.stdout.write(JSON.stringify(runScenario(scenario)));
17	} catch (error) {
18	  process.stderr.write(`${(error as Error).message}\n`);
19	  process.exitCode = 1;
20	}
