// Counts repeats among plain type names. Callers project whatever they hold
// (insured items, damage entries) down to the type strings they want counted,
// so nothing has to be dressed up as an Item just to be tallied.
const countOccurrences = (values: string[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const value of values) {
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }
  return counts;
};

const typesOf = (items: Item[]): string[] => items.map((item) => item.type);

// The counterpart of typesOf for the other side of a claim. Both feed
// countOccurrences, which compares insured types against damaged ones.
const damagedTypesOf = (damages: Damage[]): string[] =>
  damages.map((damage) => damage.itemType);

